nextflow_process {

    name "Test Process UMITOOLS_GROUP"
    script "../main.nf"
    process "UMITOOLS_GROUP"

    tag "modules"
    tag "modules_nfcore"
    tag "umitools"
    tag "umitools/extract"
    tag "umitools/group"
    tag "bwa/index"
    tag "bwa/mem"
    tag "samtools/index"

    setup {
        run("UMITOOLS_EXTRACT") {
            script "../../extract/main.nf"
            config "./nextflow.config"
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        run("BWA_INDEX") {
            script "../../../bwa/index/main.nf"
            process {
                """
                input[0] = [
                    [ id:'sarscov2'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        run("BWA_MEM") {
            script "../../../bwa/mem/main.nf"
            process {
                """
                input[0] = UMITOOLS_EXTRACT.out.reads
                input[1] = BWA_INDEX.out.index
                input[2] = [ [], [] ]
                input[3] = true
                """
            }
        }

        run("SAMTOOLS_INDEX") {
            script "../../../samtools/index/main.nf"
            process {
                """
                input[0] = BWA_MEM.out.bam
                """
            }
        }

    }

    test("no_umi") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true)
                ]
                input[1] = true
                input[2] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["log"])).match() }
            )
        }

    }

    test("with_umi - create only bam") {

        when {
            process {
                """
                input[0] = BWA_MEM.out.bam.join(SAMTOOLS_INDEX.out.index, by: [0])
                input[1] = true
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["log"])).match() }
            )
        }

    }

    test("with_umi - create bam and tsv") {

        when {
            process {
                """
                input[0] = BWA_MEM.out.bam.join(SAMTOOLS_INDEX.out.index, by: [0])
                input[1] = true
                input[2] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["log"])).match() }
            )
        }

    }

    test("with_umi - stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = BWA_MEM.out.bam.join(SAMTOOLS_INDEX.out.index, by: [0])
                input[1] = true
                input[2] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

